package com.hiretrack.web;
import com.hiretrack.model.User; import com.hiretrack.repo.UserRepository; import com.hiretrack.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
 record Credentials(@Email @NotBlank String email,@Size(min=8) String password){} record Registration(@Email @NotBlank String email,@Size(min=8) String password,String role,String firstName,String lastName,String phone,String city,String skills,String companyName){} 
 private final UserRepository repo; private final PasswordEncoder encoder; private final JwtService jwt; private final JdbcTemplate db;
 public AuthController(UserRepository r,PasswordEncoder e,JwtService j,JdbcTemplate d){repo=r;encoder=e;jwt=j;db=d;}
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Registration x){if(repo.findByEmail(x.email()).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","Email already registered"));String role="RECRUITER".equalsIgnoreCase(x.role())?"RECRUITER":"CANDIDATE";Long profileId;if("RECRUITER".equals(role)){Long companyId=db.queryForObject("INSERT INTO companies(name,industry,location) VALUES (?,?,?) RETURNING id",Long.class,(x.companyName()==null||x.companyName().isBlank()?"New HireTrack Company":x.companyName()),"Technology",x.city()==null?"Remote":x.city());profileId=db.queryForObject("INSERT INTO recruiters(company_id,name,email) VALUES (?,?,?) RETURNING id",Long.class,companyId,(x.firstName()==null?x.email().split("@")[0]:x.firstName())+" "+(x.lastName()==null?"":x.lastName()),x.email());}else{profileId=db.queryForObject("INSERT INTO candidates(first_name,last_name,email,city,skills) VALUES (?,?,?,?,?) RETURNING id",Long.class,x.firstName()==null?"":x.firstName(),x.lastName()==null?"":x.lastName(),x.email(),x.city()==null?"Remote":x.city(),x.skills()==null?"":x.skills());}User u=new User();u.setEmail(x.email());u.setPasswordHash(encoder.encode(x.password()));u.setRole(role);if("RECRUITER".equals(role))u.setRecruiterId(profileId);else u.setCandidateId(profileId);repo.save(u);return ResponseEntity.status(201).body(Map.of("token",jwt.token(u.getEmail(),u.getRole()),"role",u.getRole(),"email",u.getEmail()));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Credentials x){return repo.findByEmail(x.email()).filter(User::isActive).filter(u->encoder.matches(x.password(),u.getPasswordHash())).<ResponseEntity<?>>map(u->ResponseEntity.ok(Map.of("token",jwt.token(u.getEmail(),u.getRole()),"role",u.getRole(),"email",u.getEmail()))).orElseGet(()->ResponseEntity.status(401).body(Map.of("error","Invalid credentials")));}
}
